  `phone_number` char(15) DEFAULT NULL COMMENT '手机号',
  `note_content` varchar(1024) DEFAULT NULL COMMENT '短信内容',
  `note_params` json DEFAULT NULL COMMENT '短信参数',
  `send_user_type` tinyint DEFAULT '1' COMMENT '发送类型，1-系统，2-租户',
  `send_sys_user_id` bigint DEFAULT NULL COMMENT '发送人id',
  `send_app_user_id` bigint DEFAULT NULL COMMENT '发送人id',
  `send_store_id` bigint DEFAULT NULL COMMENT '发送门店id',
  `send_status` tinyint DEFAULT '1' COMMENT '发送状态，1-已发送，2-发送失败，3-回执发送成功，4-回执发送失败',
  `error_code` varchar(255) DEFAULT NULL COMMENT '错误码',
