DROP FUNCTION IF EXISTS `get_menu_child_ids`;
DELIMITER //
CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `get_menu_child_ids`(in_id varchar(50)) RETURNS text CHARSET utf8mb4
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE ids TEXT DEFAULT '';

    DECLARE tempids TEXT;

    SET tempids = in_id;

    WHILE tempids IS NOT NULL DO
        SET ids = CONCAT_WS(',', ids, tempids);

        SELECT GROUP_CONCAT(menu_id) INTO tempids
        FROM sys_menu
        WHERE FIND_IN_SET(parent_id, tempids) > 0;

    END WHILE;

    RETURN TRIM(BOTH ',' FROM ids);

END//
DELIMITER ;

DROP FUNCTION IF EXISTS `get_menu_parentasc_ids`;
DELIMITER //
CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `get_menu_parentasc_ids`(rootId varchar(100)) RETURNS text CHARSET utf8mb4
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE fid TEXT DEFAULT '';

    DECLARE temp_str TEXT DEFAULT '';

    DECLARE result_str TEXT DEFAULT '';

    DECLARE temp_rootId varchar(100) DEFAULT rootId;


    WHILE temp_rootId IS NOT NULL DO
        SET fid = (SELECT parent_id FROM sys_menu WHERE menu_id = temp_rootId);

        IF fid IS NOT NULL THEN
            SET temp_str = CONCAT(temp_str, ',', fid);

            SET temp_rootId = fid;

        ELSE
            SET temp_rootId = fid;

        END IF;

    END WHILE;


    SET temp_str = TRIM(BOTH ',' FROM temp_str);


    WHILE temp_str IS NOT NULL AND LENGTH(temp_str) > 0 DO
        SET fid = SUBSTRING_INDEX(temp_str, ',', -1);

        SET result_str = CONCAT(result_str, ',', fid);

        IF LOCATE(',', temp_str) > 0 THEN
            SET temp_str = SUBSTRING(temp_str, 1, LENGTH(temp_str) - LENGTH(fid) - 1);

            SET temp_str = TRIM(BOTH ',' FROM temp_str);

        ELSE
            SET temp_str = '';

        END IF;

    END WHILE;


    SET result_str = CONCAT(TRIM(BOTH ',' FROM result_str), ',', rootId);

    RETURN result_str;

END//
DELIMITER ;

DROP FUNCTION IF EXISTS `get_menu_parent_ids`;
DELIMITER //
CREATE DEFINER=`root`@`127.0.0.1` FUNCTION `get_menu_parent_ids`(rootId varchar(100)) RETURNS text CHARSET utf8mb4
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE fid TEXT DEFAULT '';

    DECLARE str TEXT DEFAULT rootId;


    WHILE rootId IS NOT NULL DO
        SET fid = (SELECT parent_id FROM sys_menu WHERE menu_id = rootId);

        IF fid IS NOT NULL THEN
            SET str = CONCAT(str, ',', fid);

            SET rootId = fid;

        ELSE
            SET rootId = fid;

        END IF;

    END WHILE;


    RETURN str;

END//
DELIMITER ;

